remarks.para:
Usage with builder:

public class MyCustomRegistrations : IWantsToRegisterStuff
{
    public void Register(IRegistrar registrar)
    {
        registrar.RegisterConstant<IMyService>(() => new MyService());
        registrar.RegisterLazySingleton<IMyViewModel>(() => new MyViewModel());
    }
}
// In your app initialization:
RxAppBuilder.CreateReactiveUIBuilder()
    .WithCoreServices()
    .WithPlatformServices()
    .WithRegistration(new MyCustomRegistrations())
    .BuildApp();
